// Validate and enrich GTM event
const items = $input.all();
const enriched = [];

for (const item of items) {
  const body = item.json.body || item.json;

  // Validate required fields
  const required = ['event', 'session_id', 'timestamp'];
  const missing = required.filter(f => !body[f]);
  if (missing.length > 0) {
    continue; // Skip invalid events
  }

  // Enrich with computed fields
  const pageUrl = body.page || body.page_url || '';
  const urlParts = pageUrl.split('/');

  // Detect vertical from URL
  let vertical = 'solar';
  if (pageUrl.includes('ev') || pageUrl.includes('mobilidade') || pageUrl.includes('wallbox') || pageUrl.includes('carregador')) {
    vertical = 'ev';
  } else if (pageUrl.includes('solar') && pageUrl.includes('ev')) {
    vertical = 'hybrid';
  }

  // Detect audience from URL
  let audience = 'b2c';
  if (pageUrl.includes('empresa') || pageUrl.includes('comercial') || pageUrl.includes('industrial') || pageUrl.includes('b2b')) {
    audience = 'b2b';
  }

  // Extract category from URL slug
  let category = '';
  if (pageUrl.includes('/categories/')) {
    const catIndex = urlParts.indexOf('categories');
    if (catIndex >= 0 && urlParts[catIndex + 1]) {
      category = urlParts[catIndex + 1];
    }
  }

  // Extract company ID if present
  let companyId = null;
  if (pageUrl.includes('/companies/') || pageUrl.includes('/empresa/')) {
    const compIndex = urlParts.findIndex(p => p === 'companies' || p === 'empresa');
    if (compIndex >= 0 && urlParts[compIndex + 1]) {
      companyId = parseInt(urlParts[compIndex + 1]);
    }
  }

  enriched.push({
    json: {
      event_name: body.event,
      user_session_id: body.session_id || body.client_id,
      user_id: body.user_id || null,
      page_url: pageUrl,
      city: body.city || null,
      state: body.state || null,
      company_id: companyId || body.company_id || null,
      category_id: body.category_id || null,
      category_slug: category,
      vertical: vertical,
      audience: audience,
      utm_source: body.utm_source || null,
      utm_medium: body.utm_medium || null,
      utm_campaign: body.utm_campaign || null,
      utm_content: body.utm_content || null,
      referrer: body.referrer || null,
      metadata: {
        user_agent: body.user_agent || null,
        screen_resolution: body.screen_resolution || null,
        language: body.language || null
      },
      created_at: body.timestamp || new Date().toISOString()
    }
  });
}

return enriched;
